cd /workspace/project && python3 - <<'EOF'
import ast, sys
for path in ['driver.py','envelope.py','validate.py','syntax.py','ebpf/helper.py','ebpf/create_dfa.py','compiler/automata.py','compiler/compiler.py']:
    src = open(path).read()
    tree = ast.parse(src)
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names: imported.add(alias.asname or alias.name.split('.')[0])
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names: imported.add(alias.asname or alias.name)
    names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name): names.add(node.id)
        if isinstance(node, ast.Attribute): pass
    text = src
    unused = [i for i in imported if text.count(i) <= 1]
    if unused: print(path, 'possibly unused imports:', unused)
EOF
